'use strict';

const {
  DEFAULT_BASE_URL,
  DEFAULT_TIMEOUT_MS,
  DEFAULT_RETRIES,
  RETRY_BASE_DELAY_MS,
  ENDPOINTS,
} = require('./constants');
const { MediaDownloaderError, ERROR_CODES } = require('./errors');

const USER_AGENT = '@satorufx/mediadownloader (+https://api.satoru.click)';

const sleep = (ms) => new Promise((done) => setTimeout(done, ms));

/** Transient statuses worth a second attempt. */
function isRetryableStatus(status) {
  return status === 429 || status === 502 || status === 503 || status === 504 || status === 521;
}

/** Build the full request URL for an endpoint. */
function buildUrl(baseUrl, endpoint, targetUrl, extraParams = {}) {
  const config = ENDPOINTS[endpoint];
  if (!config) {
    throw new MediaDownloaderError(`Unsupported endpoint: ${endpoint}`, {
      code: ERROR_CODES.UNKNOWN_ENDPOINT,
      endpoint,
    });
  }

  const url = new URL(`/api/${endpoint}`, baseUrl);
  url.searchParams.set(config.param, targetUrl);

  // Only attach params the endpoint actually accepts.
  for (const key of config.extra || []) {
    const value = extraParams[key];
    if (value !== undefined && value !== null && value !== '') {
      url.searchParams.set(key, String(value));
    }
  }

  return url.toString();
}

/** Read rate-limit headers, when present. */
function readRateLimit(headers) {
  const limit = headers.get('x-ratelimit-limit');
  if (!limit) return null;

  return {
    limit: Number(limit),
    remaining: Number(headers.get('x-ratelimit-remaining')),
    reset: headers.get('x-ratelimit-reset'),
  };
}

/**
 * Call one endpoint, retrying transient failures with exponential backoff.
 * @returns {Promise<{body: object, status: number, rateLimit: object|null}>}
 */
async function requestOnce(baseUrl, endpoint, targetUrl, options = {}) {
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  const retries = options.retries ?? DEFAULT_RETRIES;
  const requestUrl = buildUrl(baseUrl, endpoint, targetUrl, options.params || {});

  let lastError = null;

  for (let attempt = 0; attempt <= retries; attempt += 1) {
    if (attempt > 0) await sleep(RETRY_BASE_DELAY_MS * 2 ** (attempt - 1));

    let response;
    try {
      response = await fetch(requestUrl, {
        headers: {
          Accept: 'application/json',
          'User-Agent': options.userAgent || USER_AGENT,
          ...(options.headers || {}),
        },
        signal: AbortSignal.timeout(timeoutMs),
      });
    } catch (cause) {
      const timedOut = cause.name === 'TimeoutError' || /abort|timeout/i.test(cause.message);
      lastError = new MediaDownloaderError(
        timedOut ? `Timed out after ${timeoutMs}ms` : `Network error: ${cause.message}`,
        { code: timedOut ? ERROR_CODES.TIMEOUT : ERROR_CODES.NETWORK, endpoint }
      );
      continue;
    }

    const rateLimit = readRateLimit(response.headers);
    const raw = await response.text();

    let body = null;
    try {
      body = JSON.parse(raw);
    } catch {
      // Handled below.
    }

    if (response.ok && body) return { body, status: response.status, rateLimit };

    if (response.ok && !body) {
      lastError = new MediaDownloaderError('API returned a non-JSON body', {
        code: ERROR_CODES.BAD_JSON,
        status: response.status,
        endpoint,
      });
      continue;
    }

    const message =
      body?.error?.message || body?.error || body?.message || `API returned HTTP ${response.status}`;

    lastError = new MediaDownloaderError(String(message).slice(0, 300), {
      code: response.status === 429 ? ERROR_CODES.RATE_LIMITED : ERROR_CODES.UPSTREAM,
      status: response.status,
      endpoint,
    });

    if (!isRetryableStatus(response.status)) break;
  }

  throw lastError;
}

module.exports = { requestOnce, buildUrl, readRateLimit, isRetryableStatus, DEFAULT_BASE_URL };
